DROP TABLE IF EXISTS `tblcropagriculturalreferences`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `tblcropagriculturalreferences` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `crop_name` varchar(100) NOT NULL,
  `category` varchar(20) NOT NULL,
  `variety_name` varchar(255) NOT NULL,
  `days_to_maturity` int(10) unsigned NOT NULL CHECK (`days_to_maturity` >= 0),
  `days_to_maturity_min` int(10) unsigned DEFAULT NULL CHECK (`days_to_maturity_min` >= 0),
  `days_to_maturity_max` int(10) unsigned DEFAULT NULL CHECK (`days_to_maturity_max` >= 0),
  `source_name` varchar(150) NOT NULL,
  `source_url` varchar(500) NOT NULL,
  `description` longtext NOT NULL,
  `soil_type` varchar(100) NOT NULL,
  `irrigation_info` varchar(150) NOT NULL,
  `verified_date` date NOT NULL,
  `is_active` tinyint(1) NOT NULL,
  `created_at` datetime(6) NOT NULL,
  `updated_at` datetime(6) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `tblcropagriculturalreferences_crop_name_12707542` (`crop_name`),
  KEY `tblcropagriculturalreferences_category_b430d1ae` (`category`),
  KEY `tblcropagriculturalreferences_variety_name_dec4ae19` (`variety_name`)
) ENGINE=InnoDB AUTO_INCREMENT=75 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

