INSERT INTO `tblcropagriculturalreferences` VALUES (1,'Rice','grain','NSIC Rc 402',114,110,116,'Binhing Palay','https://binhingpalay.philrice.gov.ph/variety/details/NSIC%20Rc%20402','Tubigan 37. High yielding inbred rice variety with intermediate amylose content, high milling recovery, and tolerance to rice blast.','Clay Loam','Irrigated Lowland','2026-01-15',1,'2026-11-16 18:46:25.622129','2026-11-17 03:02:12.648906'),(2,'Rice','grain','NSIC Rc 222',114,106,114,'Binhing Palay','https://binhingpalay.philrice.gov.ph/variety/details/NSIC%20Rc%20222','Tubigan 18 (\'Triple 2\'). High yield potential up to 10 t/ha, resistant to bacterial leaf blight and blast. Excellent tillering ability.','Clay Loam','Irrigated Lowland','2026-01-15',1,'2026-11-16 18:46:25.631233','2026-11-17 03:02:12.653607'),(3,'Rice','grain','NSIC Rc 216',112,104,112,'Binhing Palay','https://binhingpalay.philrice.gov.ph/variety/details/NSIC%20Rc%20216','Tubigan 17. High yielding inbred variety with good eating quality, resistant to brown planthopper and green leafhopper.','Silt Loam','Irrigated Lowland','2026-01-15',1,'2026-11-16 18:46:25.641457','2026-11-17 03:02:12.657013'),(4,'Rice','grain','NSIC Rc 160',107,107,122,'Binhing Palay','https://binhingpalay.philrice.gov.ph/variety/details/NSIC%20Rc%20160','Tubigan 14. Premium grain eating quality with low amylose content; tender and aromatic texture preferred in consumer markets.','Clay Loam','Irrigated Lowland','2026-01-15',1,'2026-11-16 18:46:25.647617','2026-11-17 03:02:12.660598'),(5,'Rice','grain','PSB Rc 82',110,105,110,'Binhing Palay','https://binhingpalay.philrice.gov.ph/variety/details/PSB%20Rc%2082','Peñaranda. Nationally recommended inbred rice variety with high stability and wide adaptability across Philippine agro-ecosystems.','Clay Loam','Irrigated Lowland','2026-01-15',1,'2026-11-16 18:46:25.654166','2026-11-17 03:02:12.663491'),(6,'Rice','grain','NSIC Rc 480',107,105,110,'Binhing Palay','https://binhingpalay.philrice.gov.ph/variety/details/NSIC%20Rc%20480','GSR 8 (Green Super Rice). Bred for abiotic stress tolerance, drought resilience, and input-efficiency in rainfed areas.','Loam','Rainfed Lowland / Drought-prone','2026-01-15',1,'2026-11-16 18:46:25.660219','2026-11-17 03:02:12.667317'),(7,'Rice','grain','NSIC Rc 300',115,112,118,'Binhing Palay','https://binhingpalay.philrice.gov.ph/variety/details/NSIC%20Rc%20300','Tubigan 24. Heavy panicle variety with sturdy lodging resistance and strong vegetative vigor.','Clay Loam','Irrigated Lowland','2026-01-15',1,'2026-11-16 18:46:25.669019','2026-11-17 03:02:12.670852'),(8,'Rice','grain','PSB Rc 18',123,120,126,'Binhing Palay','https://binhingpalay.philrice.gov.ph/variety/details/PSB%20Rc%2018','Ala. Full season inbred variety with high grain recovery and high milling potential.','Clay Loam','Irrigated Lowland','2026-01-15',1,'2026-11-16 18:46:25.675397','2026-11-17 03:02:12.674337'),(9,'Rice','grain','NSIC Rc 9',119,115,123,'PhilRice','https://www.philrice.gov.ph/rice-varieties/upland-rice/','Apo. Official PhilRice upland rice variety recommendation for rainfed slopes and non-irrigated plateaus.','Sandy Loam','Upland / Rainfed','2026-01-15',1,'2026-11-16 18:46:25.683366','2026-11-17 03:02:12.677751'),(10,'Rice','grain','NSIC Rc 238',110,108,113,'PhilRice','https://www.philrice.gov.ph/rice-varieties/irrigated-lowland/','Tubigan 21. Excellent seedling vigor, heavy 1000-grain weight, and proven field stability across Luzon and Visayas.','Clay Loam','Irrigated Lowland','2026-01-15',1,'2026-11-16 18:46:25.689362','2026-11-17 03:02:12.680555'),(11,'Rice','grain','NSIC Rc 436',112,109,115,'PhilRice','https://www.philrice.gov.ph/rice-varieties/irrigated-lowland/','Tubigan 39. Outstanding head rice recovery, resistance to tungro virus, and moderate resistance to bacterial blight.','Clay Loam','Irrigated Lowland','2026-01-15',1,'2026-11-16 18:46:25.696489','2026-11-17 03:02:12.684358'),(12,'Rice','grain','NSIC Rc 27',122,118,125,'PhilRice','https://www.philrice.gov.ph/rice-varieties/rainfed-lowland/','Cabahug. High-tillering rainfed lowland variety with drought recovery capability.','Loam','Rainfed Lowland','2026-01-15',1,'2026-11-16 18:46:25.704469','2026-11-17 03:02:12.687702'),(13,'Rice','grain','Malagkit 1',118,115,122,'PhilRice','https://www.philrice.gov.ph/rice-varieties/specialty/','NSIC Rc 19. Certified glutinous rice variety with uniform amylose and excellent sticky texture for local food processing.','Clay Loam','Irrigated Lowland','2026-01-15',1,'2026-11-16 18:46:25.712396','2026-11-17 03:02:12.691266'),(14,'Tomato','vegetable','Diamante Max',65,60,70,'Agricultural Training Institute (ATI)','https://ati.da.gov.ph/ati-main/technoguides/tomato-production-guide','High yielding semi-determinate tomato variety with outstanding bacterial wilt resistance; recommended in ATI lowland vegetable production guides.','Sandy Loam','Drip / Furrow Irrigated','2026-01-15',1,'2026-11-16 18:46:25.720889','2026-11-17 03:02:12.694745'),(15,'Tomato','vegetable','Apollo',70,65,75,'Agricultural Training Institute (ATI)','https://ati.da.gov.ph/ati-main/technoguides/tomato-production-guide','Heat-tolerant open-pollinated tomato variety with thick pericarp suitable for long-distance transport.','Loam','Furrow Irrigated','2026-01-15',1,'2026-11-16 18:46:25.728734','2026-11-17 03:02:12.698253'),(16,'Eggplant','vegetable','Dumaguete Long Purple',80,75,85,'Agricultural Training Institute (ATI)','https://ati.da.gov.ph/ati-main/technoguides/eggplant-production-guide','Standard open-pollinated purple eggplant cultivar with continuous harvesting up to 4 months.','Sandy Loam','Furrow Irrigated','2026-01-15',1,'2026-11-16 18:46:25.735553','2026-11-17 03:02:12.702193'),(17,'Eggplant','vegetable','Casino 901',75,70,80,'Agricultural Training Institute (ATI)','https://ati.da.gov.ph/ati-main/technoguides/eggplant-production-guide','Vigorous F1 hybrid eggplant with deep glossy dark purple skin, uniform fruit size, and long shelf life.','Clay Loam','Drip / Furrow Irrigated','2026-01-15',1,'2026-11-16 18:46:25.742218','2026-11-17 03:02:12.705327'),(18,'Ampalaya','vegetable','Galaxy Max F1',65,60,70,'Agricultural Training Institute (ATI)','https://ati.da.gov.ph/ati-main/technoguides/ampalaya-production-guide','Prolific hybrid bitter gourd with thick ridges and intermediate fruit length; excellent disease tolerance.','Sandy Loam','Drip Irrigated with Trellis','2026-01-15',1,'2026-11-16 18:46:25.749795','2026-11-17 03:02:12.708765'),(19,'Pechay','vegetable','Black Behi',30,25,35,'Agricultural Training Institute (ATI)','https://ati.da.gov.ph/ati-main/technoguides/pechay-production-guide','Fast-growing non-heading brassica leafy vegetable; dark green leaves with broad white petioles; ideal for quick-turnaround cycles.','Loam','Sprinkler / Manual Watering','2026-01-15',1,'2026-11-16 18:46:25.757523','2026-11-17 03:02:12.711730'),(20,'Okra','vegetable','Smooth Green',55,50,60,'Agricultural Training Institute (ATI)','https://ati.da.gov.ph/ati-main/technoguides/okra-production-guide','Early maturing spineless okra variety with tender pods; high consumer demand in wet markets.','Loam','Furrow Irrigated','2026-01-15',1,'2026-11-16 18:46:25.765995','2026-11-17 03:02:12.714392'),(21,'Squash','vegetable','Suprema F1',85,80,90,'Agricultural Training Institute (ATI)','https://ati.da.gov.ph/ati-main/technoguides/squash-production-guide','Deep orange sticky flesh kalabasa with squash leaf curl virus resistance and thick flesh.','Sandy Loam','Furrow Irrigated','2026-01-15',1,'2026-11-16 18:46:25.773421','2026-11-17 03:02:12.717867'),(22,'Onion','vegetable','Red Pinoy',110,105,120,'Agricultural Training Institute (ATI)','https://ati.da.gov.ph/ati-main/technoguides/onion-production-guide','Short-day red bulb onion variety with tight pungent skins and superior storage stability in ambient cold storage.','Sandy Loam','Furrow / Overhead Sprinkler','2026-01-15',1,'2026-11-16 18:46:25.780958','2026-11-17 03:02:12.721024'),(23,'Garlic','vegetable','Ilocos White',115,110,120,'Agricultural Training Institute (ATI)','https://ati.da.gov.ph/ati-main/technoguides/garlic-production-guide','Traditional pungent Philippine garlic cultivar with high allicin content and firm white cloves.','Sandy Loam','Controlled Furrow Irrigated','2026-01-15',1,'2026-11-16 18:46:25.788695','2026-11-17 03:02:12.724382'),(24,'Cabbage','vegetable','Rare Ball',70,65,75,'Agricultural Training Institute (ATI)','https://ati.da.gov.ph/ati-main/technoguides/cabbage-production-guide','Heat-tolerant round cabbage hybrid proven for Philippine tropical mid-elevations and lowlands.','Loam','Drip / Sprinkler','2026-01-15',1,'2026-11-16 18:46:25.794135','2026-11-17 03:02:12.727347'),(40,'Corn','grain','IPB Var 6 (GMA Yellow Corn)',100,95,105,'Agricultural Training Institute (ATI)','https://ati.da.gov.ph/ati-main/technoguides/corn-production-guide','Open-pollinated yellow flint corn variety with good field stand and adaptability; a standard ATI corn production reference.','Clay Loam','Rainfed / Furrow Irrigated','2026-01-15',1,'2026-11-17 03:02:08.552700','2026-11-17 03:02:12.730022'),(41,'Sugarcane','other','Phil 84-77',330,300,360,'Agricultural Training Institute (ATI)','https://ati.da.gov.ph/ati-main/technoguides/sugarcane-production-guide','High sucrose content and heavy tonnage sugarcane cultivar recommended in ATI sugarcane production guides.','Sandy Loam','Rainfed Lowland / Furrow Irrigated','2026-01-15',1,'2026-11-17 03:02:08.555147','2026-11-17 03:02:12.732795'),(42,'Mango','fruit','Carabao (Sweet Elena)',120,110,130,'Bureau of Plant Industry (BPI)','https://library.buplant.da.gov.ph/','Premier national sweet mango selection; BPI reckons maturity about 120 days from full flower induction/bloom.','Deep Loam','Rainfed / Basin Irrigation','2026-01-15',1,'2026-11-17 03:02:08.557772','2026-11-17 03:02:12.736458'),(43,'Mango','fruit','Pico',110,105,115,'Bureau of Plant Industry (BPI)','https://library.buplant.da.gov.ph/','Slightly earlier polyembryonic mango than Carabao; harvest about 110 days after bloom.','Loam','Rainfed / Basin Irrigation','2026-01-15',1,'2026-11-17 03:02:08.560608','2026-11-17 03:02:12.739386'),(44,'Banana','fruit','Lakatan',270,240,300,'Bureau of Plant Industry (BPI)','https://library.buplant.da.gov.ph/','Premium dessert banana; BPI production guide reckons about 9 months from planting to first harvest.','Clay Loam','Rainfed / Drip Irrigated','2026-01-15',1,'2026-11-17 03:02:08.562842','2026-11-17 03:02:12.742607'),(45,'Banana','fruit','Cavendish (Grand Nain)',270,250,300,'Bureau of Plant Industry (BPI)','https://library.buplant.da.gov.ph/','Standard export commercial Cavendish cultivar with compact pseudostem and large cylindrical bunches.','Clay Loam','Drip / Under-canopy Sprinkler','2026-01-15',1,'2026-11-17 03:02:08.564987','2026-11-17 03:02:12.745152'),(46,'Banana','fruit','Saba',300,270,330,'Bureau of Plant Industry (BPI)','https://library.buplant.da.gov.ph/','Cooking/processing banana with sturdy bunch; harvest around 10 months from planting.','Loam','Rainfed','2026-01-15',1,'2026-11-17 03:02:08.567847','2026-11-17 03:02:12.747619'),(47,'Lanzones','fruit','Longkong',120,110,130,'Bureau of Plant Industry (BPI)','https://library.buplant.da.gov.ph/','BPI production guide reckons lanzones fruit about 120 days from flowering to maturity.','Loam','Rainfed / Basin Irrigation','2026-01-15',1,'2026-11-17 03:02:08.570613','2026-11-17 03:02:12.751182'),(48,'Durian','fruit','Puyat',120,115,125,'Bureau of Plant Industry (BPI)','https://library.buplant.da.gov.ph/','Leading Philippine durian cultivar; fruit matures about 120 days after flowering.','Deep Loam','Rainfed / Basin Irrigation','2026-01-15',1,'2026-11-17 03:02:08.573068','2026-11-17 03:02:12.754094'),(49,'Durian','fruit','Monthong',125,120,130,'Bureau of Plant Industry (BPI)','https://library.buplant.da.gov.ph/','Mild, thick-fleshed durian cultivar; slightly later than Puyat at about 125 days after flowering.','Deep Loam','Rainfed / Basin Irrigation','2026-01-15',1,'2026-11-17 03:02:08.575693','2026-11-17 03:02:12.757023'),(50,'Papaya','fruit','Sinta',180,150,210,'Bureau of Plant Industry (BPI)','https://library.buplant.da.gov.ph/','Popular hybrid papaya; begins bearing about 6 months after transplanting under BPI recommendations.','Loam','Furrow / Drip Irrigated','2026-01-15',1,'2026-11-17 03:02:08.579118','2026-11-17 03:02:12.760182'),(51,'Pineapple','fruit','Smooth Cayenne',540,480,600,'Bureau of Plant Industry (BPI)','https://library.buplant.da.gov.ph/','Standard processing pineapple; BPI guide reckons about 18 months from planting to first harvest.','Sandy Loam','Rainfed / Furrow Irrigated','2026-01-15',1,'2026-11-17 03:02:08.581067','2026-11-17 03:02:12.762755'),(52,'Watermelon','fruit','Sugar Sweet',75,70,80,'Bureau of Plant Industry (BPI)','https://library.buplant.da.gov.ph/','Oblong hybrid watermelon with dark green striping, crisp deep crimson flesh, and high sugar content.','Sandy Loam','Drip Irrigated with Mulch','2026-01-15',1,'2026-11-17 03:02:08.583194','2026-11-17 03:02:12.765160'),(53,'Melon','fruit','Golden Honey',70,65,75,'Bureau of Plant Industry (BPI)','https://library.buplant.da.gov.ph/','Golden smooth skin melon with salmon-colored sweet aromatic flesh and good resistance to powdery mildew.','Sandy Loam','Drip Irrigated with Plastic Mulch','2026-01-15',1,'2026-11-17 03:02:08.586489','2026-11-17 03:02:12.768763'),(54,'Eggplant','vegetable','Long Purple',80,75,85,'Bureau of Plant Industry (BPI)','https://library.buplant.da.gov.ph/','BPI-recommended open-pollinated eggplant; harvest begins about 80 days after transplanting.','Sandy Loam','Furrow Irrigated','2026-01-15',1,'2026-11-17 03:02:08.588614','2026-11-17 03:02:12.771623'),(55,'Lettuce','vegetable','Grand Rapids',40,35,45,'Bureau of Plant Industry (BPI)','https://library.buplant.da.gov.ph/','Frilled looseleaf green salad lettuce with light green crinkled leaves; slow to bolt in Philippine warm climates.','Sandy Loam','Sprinkler / Hydroponic NFT','2026-01-15',1,'2026-11-17 03:02:08.590939','2026-11-17 03:02:12.774706'),(56,'Lettuce','vegetable','Romaine',55,50,60,'Bureau of Plant Industry (BPI)','https://library.buplant.da.gov.ph/','Upright crisp-head romaine with thick midribs; BPI recommends it for cooler mid-elevation production.','Loam','Sprinkler / Drip Irrigated','2026-01-15',1,'2026-11-17 03:02:08.593475','2026-11-17 03:02:12.777522'),(57,'Cucumber','vegetable','Green Splendor',45,42,50,'Bureau of Plant Industry (BPI)','https://library.buplant.da.gov.ph/','Straight cylindrical dark green slicing cucumber with crisp mild flesh and high tolerance to downy mildew.','Loam','Drip / Furrow with Trellis','2026-01-15',1,'2026-11-17 03:02:08.595821','2026-11-17 03:02:12.779923'),(58,'Garlic','vegetable','Batanes White',110,105,115,'Bureau of Plant Industry (BPI)','https://library.buplant.da.gov.ph/','BPI-recommended white garlic with compact bulbs; harvest around 110 days after planting.','Sandy Loam','Controlled Furrow Irrigated','2026-01-15',1,'2026-11-17 03:02:08.597838','2026-11-17 03:02:12.782452'),(59,'Basil','vegetable','Balanoy (Sweet Basil)',60,55,70,'Bureau of Plant Industry (BPI)','https://library.buplant.da.gov.ph/','BPI Plant Industry Production Guide (Balanoy, Lanting, and Sambong). Aromatic herb ready for successive cutting from about 60 days.','Loam','Sprinkler / Manual Watering','2026-01-15',1,'2026-11-17 03:02:08.599971','2026-11-17 03:02:12.785918'),(60,'Mint','vegetable','Yerba Buena',45,40,60,'Bureau of Plant Industry (BPI)','https://library.buplant.da.gov.ph/','Cooling culinary and medicinal mint; BPI guide reckons first cutting from about 45 days.','Loam','Sprinkler / Manual Watering','2026-01-15',1,'2026-11-17 03:02:08.603298','2026-11-17 03:02:12.788873'),(61,'Oregano','vegetable','Suganda',60,55,75,'Bureau of Plant Industry (BPI)','https://library.buplant.da.gov.ph/','Philippine oregano used as herb and traditional remedy; ready for repeated harvest from about 60 days.','Loam','Sprinkler / Manual Watering','2026-01-15',1,'2026-11-17 03:02:08.605407','2026-11-17 03:02:12.792070'),(62,'Cilantro','vegetable','Wansoy',50,45,55,'Bureau of Plant Industry (BPI)','https://library.buplant.da.gov.ph/','Fast-growing coriander for fresh leaves and seeds; harvest from about 50 days before bolting.','Loam','Sprinkler / Manual Watering','2026-01-15',1,'2026-11-17 03:02:08.607679','2026-11-17 03:02:12.794753'),(63,'Lemongrass','vegetable','Tanglad',90,80,120,'Bureau of Plant Industry (BPI)','https://library.buplant.da.gov.ph/','Aromatic lemongrass for culinary and medicinal use; clumps can be harvested from about 3 months.','Loam','Rainfed / Sprinkler Irrigated','2026-01-15',1,'2026-11-17 03:02:08.610589','2026-11-17 03:02:12.797110'),(64,'Ginger','vegetable','Native Ginger (Luya)',240,210,270,'Bureau of Plant Industry (BPI)','https://library.buplant.da.gov.ph/','Pungent native ginger; BPI guide reckons about 8 months from planting to harvest.','Loam','Rainfed / Furrow Irrigated','2026-01-15',1,'2026-11-17 03:02:08.612923','2026-11-17 03:02:12.799742'),(65,'Turmeric','vegetable','Luyang Dilaw',270,240,300,'Bureau of Plant Industry (BPI)','https://library.buplant.da.gov.ph/','Golden turmeric for culinary, cosmetic, and medicinal use; about 9 months to full maturity.','Loam','Rainfed / Furrow Irrigated','2026-01-15',1,'2026-11-17 03:02:08.615060','2026-11-17 03:02:12.803167'),(66,'Chili Pepper','vegetable','Siling Labuyo',75,70,90,'Bureau of Plant Industry (BPI)','https://library.buplant.da.gov.ph/','Native small fiery chili; BPI guide reckons first harvest from about 75 days after transplanting.','Loam','Furrow / Drip Irrigated','2026-01-15',1,'2026-11-17 03:02:08.618005','2026-11-17 03:02:12.805918'),(67,'Black Pepper','other','Paminta',730,540,1095,'Bureau of Plant Industry (BPI)','https://library.buplant.da.gov.ph/','Vine spice; BPI guide notes vines begin bearing from about 18 months to 3 years after planting.','Loam','Rainfed / Drip Irrigated','2026-01-15',1,'2026-11-17 03:02:08.620633','2026-11-17 03:02:12.809112'),(68,'Cassava','vegetable','Lakan (UPL-Ca 2)',280,270,300,'Bureau of Plant Industry (BPI)','https://library.buplant.da.gov.ph/','High starch cassava for industrial and food use; BPI guide reckons about 9 months to maturity.','Sandy Loam','Rainfed Upland','2026-01-15',1,'2026-11-17 03:02:08.622986','2026-11-17 03:02:12.811845'),(69,'Cassava','vegetable','Golden Yellow',240,210,270,'Bureau of Plant Industry (BPI)','https://library.buplant.da.gov.ph/','Early maturing food-grade cassava with tender yellow boiling roots and low cyanogenic glycoside content.','Sandy Loam','Rainfed Upland','2026-01-15',1,'2026-11-17 03:02:08.625491','2026-11-17 03:02:12.814515'),(70,'Sweet Potato','vegetable','Super Ambing (NSIC Sp 30)',110,100,120,'Bureau of Plant Industry (BPI)','https://library.buplant.da.gov.ph/','Orange-fleshed sweet potato with high beta-carotene content; BPI guide reckons about 110 days to harvest.','Sandy Loam','Rainfed / Furrow Irrigated','2026-01-15',1,'2026-11-17 03:02:08.628149','2026-11-17 03:02:12.818058'),(71,'Peanut','vegetable','NSIC Pn 14 (UPL Pn 12)',110,105,115,'Bureau of Plant Industry (BPI)','https://library.buplant.da.gov.ph/','High pod yield and large seed size; BPI guide reckons about 110 days from planting.','Sandy Loam','Rainfed / Overhead Sprinkler','2026-01-15',1,'2026-11-17 03:02:08.630425','2026-11-17 03:02:12.821067'),(72,'Taro','vegetable','Gabi',180,150,240,'Bureau of Plant Industry (BPI)','https://library.buplant.da.gov.ph/','Edible taro for leaves and corms; BPI guide reckons about 6 months from planting.','Loam','Rainfed / Flood Irrigated','2026-01-15',1,'2026-11-17 03:02:08.632571','2026-11-17 03:02:12.824275'),(73,'Ube','vegetable','Purple Yam',240,210,270,'Bureau of Plant Industry (BPI)','https://library.buplant.da.gov.ph/','Violet-fleshed yam for desserts and processing; BPI guide reckons about 8 months to maturity.','Loam','Rainfed / Furrow Irrigated','2026-01-15',1,'2026-11-17 03:02:08.635893','2026-11-17 03:02:12.827224'),(74,'Jicama','vegetable','Singkamas',120,100,150,'Bureau of Plant Industry (BPI)','https://library.buplant.da.gov.ph/','Crisp sweet root crop eaten fresh; BPI guide reckons about 4 months from planting.','Sandy Loam','Furrow Irrigated','2026-01-15',1,'2026-11-17 03:02:08.638164','2026-11-17 03:02:12.829794');
