--
-- Table structure for table `tblcrops`
--

DROP TABLE IF EXISTS `tblcrops`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `tblcrops` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `name` varchar(255) NOT NULL,
  `variety` varchar(255) NOT NULL,
  `planting_date` date NOT NULL,
  `status` varchar(30) NOT NULL,
  `area_hectares` decimal(10,2) NOT NULL,
  `notes` longtext NOT NULL,
  `created_at` datetime(6) NOT NULL,
  `updated_at` datetime(6) NOT NULL,
  `farm_id` bigint(20) NOT NULL,
  `user_id` int(11) DEFAULT NULL,
  `expected_harvest_date` date DEFAULT NULL,
  `actual_harvest_date` date DEFAULT NULL,
  `category` varchar(20) NOT NULL,
  `days_to_maturity` int(10) unsigned NOT NULL CHECK (`days_to_maturity` >= 0),
  `estimated_yield` decimal(8,2) DEFAULT NULL,
  `harvest_season` varchar(100) NOT NULL,
  `image` varchar(100) DEFAULT NULL,
  `quality` varchar(30) NOT NULL,
  `reference_source` varchar(255) NOT NULL,
  `reference_url` varchar(500) NOT NULL,
  `soil_type` varchar(100) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `tblcrops_farm_id_b9fc73ae_fk_tblfarms_id` (`farm_id`),
  KEY `tblcrops_user_id_791cce3c_fk_auth_user_id` (`user_id`),
  KEY `tblcrops_category_5bf6bece` (`category`),
  CONSTRAINT `tblcrops_farm_id_b9fc73ae_fk_tblfarms_id` FOREIGN KEY (`farm_id`) REFERENCES `tblfarms` (`id`),
  CONSTRAINT `tblcrops_user_id_791cce3c_fk_auth_user_id` FOREIGN KEY (`user_id`) REFERENCES `auth_user` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=152 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `tblcrops`
